# check shape counts per color
from collections import defaultdict
def shapes(g):
    seen=set(); res=defaultdict(list)
    for r in range(10):
        for c in range(10):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; stack=[(r,c)]; comp=set()
                while stack:
                    p=stack.pop()
                    if p in seen: continue
                    seen.add(p); comp.add(p)
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        q=(p[0]+dr,p[1]+dc)
                        if 0<=q[0]<10 and 0<=q[1]<10 and g[q[0]][q[1]]==col and q not in seen: stack.append(q)
                res[col].append(sorted(comp))
    return res
